    if(e.target.closest('[data-pdf]')) return pdfDeLinhas(REPID[p.representada]||'',{n:p.cliente,cnpj:p.cnpj,cid:p.cidade},its.map(i=>({cod:i.cod,desc:String(i.descricao||'').replace(i.cod+' - ',''),qt:i.qtd,pu:i.preco})),{prazo:p.prazo,oc:p.oc,vend:p.vendedor});
