      const o=curQ(rep); let n=0; its.forEach(i=>{const pr=C.find(x=>x.cod===String(i.cod)); if(!pr) return; const ex=o.itens.find(x=>x.pid===pr.id); if(ex) ex.qt+=+i.qtd; else o.itens.push({pid:pr.id,qt:+i.qtd}); n++});
