/* ================= botão Sincronizar Reprio ================= */
async function sincronizarReprio(btn){if(!RK()){toast('Coloque a chave do Reprio em Mais › Ajustes'); return go('aj')} const lb=btn?btn.textContent:''; if(btn){btn.disabled=true; btn.textContent='Sincronizando…'}
  try{const d=new Date(); d.setDate(d.getDate()-120); LIVE=null; const r=await reprioAoVivo(ymd(d),true);
    if(r.gravou){try{await api('rpc/atualizar_resumos',{method:'POST',body:'{}'})}catch(e){}}
    STALE.add('clis2'); delete CLIM.c; CLIS=null; PEDS=null;
    toast(r.gravou?`✓ ${r.rows.length} pedidos/orçamentos dos últimos 120 dias atualizados do Reprio`:r.erro?'Li o Reprio, mas não gravei: '+r.erro:`Li ${r.rows.length} pedidos do Reprio (para gravar na base é preciso ser gestor)`)}
  catch(e){toast('Reprio: '+e.message)} if(btn){btn.disabled=false; btn.textContent=lb}}

/* ================= Portal B2B: liberar acesso, tabelas e prazos por cliente ================= */
const B2B_URL='https://chamaeescritorio1-boop.github.io/medix-luvas/b2b/';
async function b2bCliente(cnpj,razao,fant){const box=$('#b2bbox'); if(!box) return; if(!cnpj){box.innerHTML='<p class="hint">Salve o cadastro primeiro.</p>';return}
  let A; try{A=await api(`b2b_acessos?select=*&cnpj=eq.${cnpj}&order=criado_em`)}catch(e){box.innerHTML='<p class="warn">Para ativar o portal, rode no Supabase o arquivo <b>7_portal_b2b.sql</b>.</p>';return}
  const R=(await reps(true)).filter(r=>r.ativa); const [CT,TA]=await Promise.all([api(`cliente_tabela?select=*&cnpj=eq.${cnpj}`).catch(()=>[]),api('tabelas?select=id,rep,nome,ativa,b2b_padrao&order=nome').catch(()=>[])]);
  const cfg={}; CT.forEach(c=>cfg[c.rep]={tabela_id:c.tabela_id,prazos:c.prazos||[]});
  const msg=`Olá! Liberamos seu acesso ao portal de pedidos da Chamae. Entre em ${B2B_URL} com o e-mail EMAIL, toque em "Primeiro acesso? Criar minha senha" e pronto: você vê nossos catálogos com os seus preços e envia pedidos direto para nós.`;
  const card=r=>{const T=TA.filter(t=>t.rep===r.id&&t.ativa!==false); const pad=T.find(t=>t.b2b_padrao); const c=cfg[r.id]||{prazos:[]}; const pzR=((r.regras||{}).prazos||[]).map(p=>p.n); const todos=[...new Set([...pzR,...(c.prazos||[])])];
    return `<div class="card grid" style="background:var(--surface2)" data-rc="${r.id}"><div class="row" style="justify-content:space-between"><b>${repIcon(r,22)} ${esc(r.nome)}</b>${c.tabela_id||(c.prazos||[]).length?'<span class="tag ok">configurado</span>':''}</div>
     ${T.length?`<label class="f">Tabela de preço<select data-bt="${r.id}"><option value="">${pad?'Usar a padrão do portal ('+esc(pad.nome)+')':'— sem tabela (preço sob consulta) —'}</option>${T.map(t=>`<option value="${t.id}"${c.tabela_id==t.id?' selected':''}>${esc(t.nome)}${t.b2b_padrao?' ★':''}</option>`).join('')}</select></label>`:'<p class="hint" style="margin:0">Nenhuma tabela cadastrada para esta fábrica.</p>'}
     <div class="hint">Prazos liberados para este cliente ${c.prazos&&c.prazos.length?'':'(nenhum marcado = cliente vê todos os prazos da fábrica)'}</div>
     <div class="row">${todos.map(p=>`<button class="chip${(c.prazos||[]).includes(p)?' on':''}" data-bpz="${r.id}" data-v="${esc(p)}">${esc(p)}</button>`).join('')||'<span class="hint">A fábrica ainda não tem prazos cadastrados.</span>'}<input data-bpn="${r.id}" placeholder="+ outro prazo" style="width:150px;padding:6px"></div></div>`};
  box.innerHTML=`${A.map(a=>`<div class="row" style="justify-content:space-between;border-bottom:1px solid var(--line);padding:6px 0"><div><b>${esc(a.email)}</b> ${a.nome?'· '+esc(a.nome):''} ${a.ativo?'<span class="tag">ativo</span>':'<span class="tag bad">bloqueado</span>'}</div><div class="row"><button class="chip" data-bwa="${esc(a.email)}">Enviar convite</button><button class="chip" data-btog="${esc(a.email)}" data-on="${a.ativo?1:0}">${a.ativo?'Bloquear':'Liberar'}</button><button class="chip" data-bdel="${esc(a.email)}">✕</button></div></div>`).join('')||'<p class="hint">Nenhum acesso liberado.</p>'}
   <div class="row"><input id="bem" type="email" placeholder="E-mail do comprador" style="flex:2;min-width:200px"><input id="bno" placeholder="Nome (opcional)" style="flex:1;min-width:140px"><button class="btn sm" id="badd">Liberar acesso</button></div>
   <b style="margin-top:10px">Tabelas e prazos deste cliente em cada fábrica</b><p class="hint" style="margin:0">Vale para o portal e para os orçamentos do sistema. Salva sozinho ao escolher. ★ = tabela padrão do portal.</p>
   <div class="dgrid">${R.map(card).join('')}</div>
   <a class="btn sm ghost" href="${B2B_URL}" target="_blank" rel="noopener">Abrir o portal (visualizar como este cliente)</a>`;
  const salvar=async rep=>{const c=cfg[rep]||{prazos:[]}; try{if(!c.tabela_id&&!(c.prazos||[]).length) await api(`cliente_tabela?cnpj=eq.${cnpj}&rep=eq.${rep}`,{method:'DELETE'}); else await api('cliente_tabela?on_conflict=cnpj,rep',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({cnpj,rep,tabela_id:c.tabela_id||null,prazos:c.prazos||[]})}); toast('Salvo')}catch(err){toast(/prazos/.test(err.message)?'Rode o arquivo 9_prazos_cliente.sql no Supabase':'Erro: '+err.message)}};
  box.onclick=async e=>{const t=e.target; try{
    const pz=t.closest('[data-bpz]'); if(pz){const rep=pz.dataset.bpz, v=pz.dataset.v; const c=cfg[rep]=cfg[rep]||{tabela_id:null,prazos:[]}; c.prazos=c.prazos.includes(v)?c.prazos.filter(x=>x!==v):[...c.prazos,v]; pz.classList.toggle('on'); return salvar(rep)}
    if(t.id==='badd'){const em=box.querySelector('#bem').value.trim().toLowerCase(); if(!/@/.test(em)) return toast('E-mail inválido'); await api('b2b_acessos?on_conflict=email',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({email:em,cnpj,nome:box.querySelector('#bno').value.trim()||null,ativo:true})}); toast('Acesso liberado'); return b2bCliente(cnpj,razao,fant)}
    const w=t.closest('[data-bwa]'); if(w){const tx=msg.replace('EMAIL',w.dataset.bwa); try{await navigator.clipboard.writeText(tx)}catch(_){} window.open('https://wa.me/?text='+encodeURIComponent(tx),'_blank'); return toast('Convite copiado')}
    const tg=t.closest('[data-btog]'); if(tg){await api(`b2b_acessos?email=eq.${encodeURIComponent(tg.dataset.btog)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({ativo:tg.dataset.on!=='1'})}); return b2bCliente(cnpj,razao,fant)}
    const d=t.closest('[data-bdel]'); if(d){if(!confirm('Remover este acesso?')) return; await api(`b2b_acessos?email=eq.${encodeURIComponent(d.dataset.bdel)}`,{method:'DELETE'}); return b2bCliente(cnpj,razao,fant)}}catch(err){toast('Erro: '+err.message)}};
  box.onchange=async e=>{const s2=e.target.closest('[data-bt]'); if(s2){const c=cfg[s2.dataset.bt]=cfg[s2.dataset.bt]||{prazos:[]}; c.tabela_id=s2.value?+s2.value:null; return salvar(s2.dataset.bt)}
    const n=e.target.closest('[data-bpn]'); if(n&&n.value.trim()){const rep=n.dataset.bpn; const c=cfg[rep]=cfg[rep]||{tabela_id:null,prazos:[]}; c.prazos=[...new Set([...c.prazos,n.value.trim()])]; await salvar(rep); b2bCliente(cnpj,razao,fant)}}}

/* ================= Equipe (gestor aprova acessos) ================= */
async function equipeView(){const m=$('#main'); if(!ehGestor()){m.innerHTML='<p class="hint">Só gestores.</p>';return} let P=[]; try{P=await api('perfis?select=id,email,nome,papel,aprovado&order=aprovado.desc,nome')}catch(e){try{P=await api('perfis?select=id,email,nome,papel&order=nome')}catch(_){}}
  let B=[]; try{B=await api('b2b_acessos?select=email')}catch(e){} const cli=new Set(B.map(b=>String(b.email).toLowerCase()));
  m.innerHTML=`<div class="row" style="justify-content:space-between"><div class="sec" style="margin:0">Equipe</div><button class="chip" data-gm2="mais">‹ Mais</button></div>
   <div class="card grid" style="margin:10px 0"><b>Como incluir alguém (ex.: Clayton)</b><p class="hint" style="margin:0">1) A pessoa abre o Sistema, toca em <b>“Criar meu acesso”</b> e cadastra e-mail e senha. 2) Ela aparece aqui como <b>pendente</b>. 3) Você escolhe o papel e toca em <b>Aprovar</b>. Ninguém entra sem a sua aprovação.</p>${P.length&&P[0].aprovado===undefined?'<p class="warn" style="margin:0">Rode o arquivo 8_equipe_aprovada.sql no Supabase para ativar a aprovação.</p>':''}</div>
   ${P.map(p=>{const ehCli=cli.has(String(p.email).toLowerCase()); return `<div class="card grid" style="margin-bottom:8px" data-pf="${p.id}"><div class="row" style="justify-content:space-between"><div><b>${esc(p.nome||p.email)}</b> <span class="hint">${esc(p.email||'')}</span></div>${ehCli?'<span class="tag">cliente B2B</span>':p.aprovado?'<span class="tag ok">aprovado</span>':'<span class="tag warn">pendente</span>'}</div>
     ${ehCli?'<p class="hint" style="margin:0">Login de cliente do portal (não acessa o sistema).</p>':`<div class="row"><input data-k="nome" value="${esc(p.nome||'')}" placeholder="Nome (igual ao Reprio)" style="flex:1"><select data-k="papel"><option value="vendedor"${p.papel==='vendedor'?' selected':''}>Vendedor</option><option value="gestor"${p.papel==='gestor'?' selected':''}>Gestor</option></select><button class="btn sm" data-ap="${p.aprovado?0:1}">${p.aprovado?'Salvar':'Aprovar'}</button>${p.aprovado&&p.id!==sess.uid?'<button class="chip" data-bloq>Bloquear</button>':''}</div>`}</div>`}).join('')}`;
  m.onclick=async e=>{const t=e.target; if(t.closest('[data-gm2]')) return go('mais'); const c=t.closest('[data-pf]'); if(!c) return; const id=c.dataset.pf; const g=k=>c.querySelector(`[data-k="${k}"]`);
    try{if(t.closest('[data-ap]')){await api(`perfis?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({nome:g('nome').value.trim()||null,papel:g('papel').value,aprovado:true})}); toast('Salvo'); return equipeView()}
      if(t.closest('[data-bloq]')){if(!confirm('Bloquear o acesso desta pessoa?')) return; await api(`perfis?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({aprovado:false})}); return equipeView()}}catch(err){toast('Erro: '+err.message)}}}

/* ================= Importar itens para o orçamento (PDF da OC, Excel, texto colado) ================= */
function loadPDFJS(){return window.pdfjsLib?Promise.resolve():new Promise((ok,bad)=>{const s=document.createElement('script'); s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js'; s.onload=()=>{window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'; ok()}; s.onerror=()=>bad(new Error('sem leitor de PDF (verifique a internet)')); document.head.appendChild(s)})}
async function textoPDF(f){await loadPDFJS(); const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise; const out=[];
  for(let i=1;i<=pdf.numPages;i++){const pg=await pdf.getPage(i); const tc=await pg.getTextContent(); const linhas={}; tc.items.forEach(it=>{const y=Math.round(it.transform[5]/3); (linhas[y]=linhas[y]||[]).push([it.transform[4],it.str])}); Object.keys(linhas).sort((a,b)=>b-a).forEach(y=>out.push(linhas[y].sort((a,b)=>a[0]-b[0]).map(x=>x[1]).join(' ')))} return out}
function lerNumBR(s){s=String(s).trim(); if(!/^\d{1,3}(\.\d{3})*(,\d+)?$|^\d+(,\d+)?$|^\d+\.\d{1,2}$/.test(s)) return null; if(/^\d+\.\d{1,2}$/.test(s)) return +s; return +s.replace(/\./g,'').replace(',','.')}
function blocosOC(linhas){const B=[]; let cur=null; const ini=/^\s*(\d{1,3}\s+)?[A-Z0-9][A-Z0-9.\-\/]{2,}\s+[A-ZÀ-Úa-zà-ú]{2,}/;
  for(const l0 of linhas){const l=String(l0); if(!l.trim()) continue; const tk=l.trim().split(/\s+/); const temNum=/\d/.test(tk[0]);
    if(temNum&&ini.test(l)&&!/^\d+([.,]\d+)?$/.test(tk[1]||'')){cur={ls:[l]}; B.push(cur)} else if(cur) cur.ls.push(l); else B.push({ls:[l],solto:1})}
  return B}
function qtdTripla(toks){const N=toks.map((t,i)=>({i,n:lerNumBR(t)})).filter(o=>o.n!=null&&o.n>0);
  for(let a=0;a<N.length;a++) for(let b=a+1;b<N.length;b++) for(let c=b+1;c<N.length;c++){const q=N[a].n,pu=N[b].n,tot=N[c].n; if(q>=1&&q<100000&&Math.abs(q*pu-tot)<=Math.max(0.05,tot*0.003)) return {qt:q,pu,tot,idx:[N[a].i,N[b].i,N[c].i]}}
  return null}
function idxCatalogo(C){const idx={}; C.forEach(p=>{[p.cod,p.ref,(p.attrs||{}).ean,(p.attrs||{}).cod_fab].filter(Boolean).forEach(k=>{const n=norm(k).replace(/\s+/g,''); if(n.length>=2&&!idx[n]) idx[n]=p})}); return idx}
const PAL=s=>norm(s).replace(/[^A-Z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>=3&&!/^\d+$/.test(w));
function porDescricao(txt,C){const W=new Set(PAL(txt)); if(W.size<2) return null; let best=null,bs=0; for(const p of C){const pw=PAL(p.descricao||''); if(!pw.length) continue; const hit=pw.filter(w=>W.has(w)).length; const sc=hit/Math.max(pw.length,3); if(hit>=2&&sc>bs){bs=sc;best=p}} return bs>=0.6?{p:best,sc:bs}:null}
function casarItens(linhas,C){const idx=idxCatalogo(C); const B=blocosOC(linhas); const temTripla=B.some(b=>qtdTripla(b.ls.join(' ').split(/\s+/)));
  const blocos=temTripla?B:linhas.map(l=>({ls:[l]})); const achou=[], faltou=[];
  for(const b of blocos){const txt=b.ls.join(' '); const toks=txt.split(/[\s;|\t]+/).map(x=>x.trim()).filter(Boolean); const tr=qtdTripla(toks); if(temTripla&&!tr) continue;
    const usados=new Set(tr?tr.idx:[]); const cands=[]; toks.forEach((t,i)=>{if(usados.has(i)) return; const n=norm(t).replace(/[^A-Z0-9.\-\/]/g,''); const p=idx[n]; if(p) cands.push({p,i,alfa:/[A-Z]/.test(n)&&/\d/.test(n),len:n.length})});
    cands.sort((x,y)=>(y.alfa-x.alfa)||((x.i===0)-(y.i===0))||(y.len-x.len)); let p=cands[0]&&cands[0].p, como='código';
    if(!p){const d=porDescricao(txt.replace(/\d+([.,]\d+)+/g,' '),C); if(d){p=d.p; como='descrição'}}
    let qt=tr?tr.qt:null; if(qt==null){const ti=cands[0]?cands[0].i:-1; const nums=toks.map((x,i)=>({i,n:lerNumBR(x)})).filter(o=>o.i!==ti&&o.n!=null&&o.n>0&&o.n<100000); const dep=nums.filter(o=>o.i>ti); qt=(dep.find(o=>Number.isInteger(o.n))||dep[0]||nums[0]||{n:1}).n}
    qt=Math.round(qt*1000)/1000; const resumo=txt.replace(/\s+/g,' ').trim().slice(0,90);
    if(p) achou.push({p,qt,ln:resumo,como,pu:tr&&tr.pu}); else if(tr) faltou.push({qt,ln:resumo,pu:tr.pu})}
  const r=achou; r.faltou=faltou; r.idx=idx; return r}
async function importarItensOrc(rep,o){const C=await catalog(rep); const P=await prices(o.tabela); const ov=document.createElement('div'); ov.className='ov';
  ov.innerHTML=`<div class="sh grid"><b style="font-size:18px">Importar itens para o orçamento ${esc(repName(rep))}</b>
   <p class="hint" style="margin:0">Suba a <b>ordem de compra em PDF</b> do cliente, uma <b>planilha</b> (Código e Quantidade) ou cole o texto. O sistema acha os códigos do catálogo (código, referência ou EAN) e as quantidades; você confere antes de incluir.</p>
   <div class="row"><input id="iof" type="file" accept=".pdf,.xlsx,.xls,.csv,.txt" style="flex:1"><button class="chip" id="iomod">Baixar modelo Excel</button></div>
   <textarea id="iot" rows="4" placeholder="Ou cole aqui: uma linha por item, ex.: 800104 20"></textarea><button class="btn ghost sm" id="iolr">Ler texto colado</button>
   <div id="iores"></div><div class="row"><button class="btn" id="ioadd" disabled>Incluir no orçamento</button><button class="btn ghost" data-x>Fechar</button></div></div>`; document.body.appendChild(ov);
  let res=[], fal=[], ocNum=''; const show=()=>{const r=ov.querySelector('#iores'); const idx=res.idx||idxCatalogo(C);
    r.innerHTML=(ocNum?`<p class="hint" style="margin:0">Nº da OC no PDF: <b>${esc(ocNum)}</b>${o.oc&&o.oc!==o.num?'':' — será usado como OC do orçamento'}</p>`:'')+
     (res.length?`<p class="hint">${res.length} item(ns) reconhecido(s). Confira a quantidade; se o produto estiver errado, digite o código certo.</p><div style="overflow-x:auto"><table class="t"><tr><th></th><th>Produto</th><th>Na OC</th><th class="n">Qtd</th></tr>${res.map((a,i)=>`<tr><td><input type="checkbox" data-ic="${i}" checked style="width:auto"></td><td><input data-icod="${i}" value="${esc(a.p.cod)}" style="width:110px;padding:5px;font-weight:700"> <span class="hint" data-idesc="${i}">${esc(String(a.p.descricao||'').slice(0,48))}</span>${a.como==='descrição'?' <span class="tag warn">achado pela descrição — confira</span>':''}${P[a.p.id]?'':' <span class="tag warn">sem preço</span>'}</td><td><small class="hint">${esc(a.ln.slice(0,70))}</small></td><td class="n"><input data-iq="${i}" type="number" step="any" value="${a.qt}" style="width:80px;padding:5px"></td></tr>`).join('')}</table></div>`:'<p class="warn">Nenhum produto do catálogo encontrado. Confira se é a representada certa ou use o modelo Excel.</p>')+
     (fal.length?`<div class="card" style="margin-top:8px"><b>${fal.length} item(ns) da OC sem correspondência</b><p class="hint" style="margin:4px 0">Digite o código do catálogo para incluir, ou deixe em branco para ignorar.</p><table class="t">${fal.map((f,i)=>`<tr><td><small>${esc(f.ln.slice(0,80))}</small></td><td><input data-fcod="${i}" placeholder="código" style="width:110px;padding:5px"></td><td class="n"><input data-fq="${i}" type="number" step="any" value="${f.qt}" style="width:80px;padding:5px"></td></tr>`).join('')}</table></div>`:'');
    ov.querySelector('#ioadd').disabled=!res.length&&!fal.length;
    r.oninput=e=>{const t=e.target; const k=t.dataset.icod; if(k==null) return; const p=idx[norm(t.value).replace(/\s+/g,'')]; const d=r.querySelector(`[data-idesc="${k}"]`); if(p){res[+k].p=p; res[+k].como='manual'; d.textContent=String(p.descricao||'').slice(0,48); t.style.borderColor=''} else {d.textContent='código não encontrado'; t.style.borderColor='var(--bad)'}}};
  ov.onclick=async e=>{const t=e.target; if(t.closest('[data-x]')||t===ov) return ov.remove();
    if(t.id==='iolr'){res=casarItens(ov.querySelector('#iot').value.split('\n'),C); fal=res.faltou||[]; return show()}
    if(t.id==='iomod'){await loadXLSX(); const ws=XLSX.utils.aoa_to_sheet([['Código','Descrição (opcional)','Quantidade'],['800104','Casco Avant Amarelo',20]]); const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb,ws,'Pedido'); return XLSX.writeFile(wb,'Modelo_pedido_Chamae.xlsx')}
    if(t.id==='ioadd'){let n=0; const idx=res.idx||idxCatalogo(C); ov.querySelectorAll('[data-fcod]').forEach(x=>{const p=idx[norm(x.value).replace(/\s+/g,'')]; if(!p) return; const q=+ov.querySelector(`[data-fq="${x.dataset.fcod}"]`).value||0; if(q>0){let it=o.itens.find(i=>i.pid===p.id); if(!it){it={pid:p.id,qt:0}; o.itens.push(it)} it.qt+=Math.ceil(q/(p.mult||1))*(p.mult||1); n++}}); if(ocNum&&(!o.oc||o.oc===o.num)) o.oc=ocNum; ov.querySelectorAll('[data-ic]').forEach(c=>{if(!c.checked) return; const a=res[+c.dataset.ic]; const q=Math.max(0,+ov.querySelector(`[data-iq="${c.dataset.ic}"]`).value||0); if(!q) return; const mu=a.p.mult||1; const qq=Math.ceil(q/mu)*mu; let it=o.itens.find(i=>i.pid===a.p.id); if(!it){it={pid:a.p.id,qt:0}; o.itens.push(it)} it.qt+=qq; n++}); saveQ(o); ov.remove(); toast(n+' itens incluídos'); return orc()}};
  ov.querySelector('#iof').onchange=async e=>{const f=e.target.files[0]; if(!f) return; const r=ov.querySelector('#iores'); r.innerHTML='<p class="hint">Lendo arquivo…</p>';
    try{let linhas=[]; if(/\.pdf$/i.test(f.name)) linhas=await textoPDF(f); else if(/\.(txt|csv)$/i.test(f.name)) linhas=(await f.text()).split(/\r?\n/); else{await loadXLSX(); const wb=XLSX.read(await f.arrayBuffer()); linhas=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:''}).map(r=>r.join('\t'))}
      const om=linhas.join('\n').match(/(?:Pedido\s+de\s+Compra|Ordem\s+de\s+Compra|O\.?\s?C\.?|Pedido)\s*(?:N[ºo°.]*|n[uú]mero)?\s*[:#]?\s*(\d{4,})/i); ocNum=om?om[1].replace(/^0+(?=\d{4})/,''):'';
      res=casarItens(linhas,C); fal=res.faltou||[]; show()}catch(err){r.innerHTML=`<p class="bad">${esc(err.message)}</p>`}}}

/* ================= Transmitir na fábrica: tudo pronto para copiar e colar ================= */
async function transmitir(o){const L2=await linhasOrc(o); const d=o.dados||{}; const c=d.cli||{}; const rep=d.rep||o.app; await reps(); const R=(REPS||[]).find(x=>x.id===rep)||{}; const portal=(R.regras||{}).portal||'';
  let cad=null; if(o.cnpj){try{cad=(await api(`clientes?select=*&cnpj=eq.${o.cnpj}`))[0]}catch(e){}}
  const T=(await tabelas(rep).catch(()=>[])).find(t=>t.id==d.tabela);
  const sub=L2.reduce((s,l)=>s+(+l.pu||0)*(+l.qt||0),0), ipi=L2.reduce((s,l)=>s+(+l.pu||0)*(+l.qt||0)*(+l.ipi||0)/100,0);
  const campos=[['CNPJ',fmtCnpj(o.cnpj||c.cnpj||'')],['CNPJ (só números)',o.cnpj||c.cnpj||''],['Razão social',(cad&&cad.razao)||o.cliente||c.n||''],['Ordem de compra',d.oc||''],['Prazo de pagamento',d.prazo||''],['Tabela',T?T.nome:''],['Data programada',d.programado?d.programado.split('-').reverse().join('/'):''],['Transportadora',d.transpN||''],['Vendedor',d.vend||'']].filter(x=>x[1]);
  const fmtN=v=>String(v).replace('.',',');
  const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="sh grid"><div class="row" style="justify-content:space-between"><b style="font-size:18px">🚚 Transmitir na fábrica · ${esc(repName(rep))}</b><button class="chip" data-x>✕</button></div>
   ${portal?`<a class="btn" href="${esc(portal)}" target="_blank" rel="noopener">Abrir portal ${esc(repName(rep))} ↗</a>`:'<p class="hint" style="margin:0">Dica: cadastre o link do portal da fábrica em Representadas › Dados.</p>'}
   ${d.obs?`<div class="card" style="border:2px solid var(--warn);background:var(--surface2)"><b class="warn">⚠️ Observação do pedido</b><div style="white-space:pre-wrap;margin:6px 0">${esc(d.obs)}</div><button class="chip" data-cp="${esc(d.obs)}">Copiar observação</button></div>`:''}
   <p class="hint" style="margin:0">Toque em cada campo para copiar e cole no portal.</p>
   ${campos.map(([l,v])=>`<button class="chip" style="text-align:left;display:flex;justify-content:space-between;gap:8px" data-cp="${esc(v)}"><span class="hint">${l}</span><b style="text-align:right">${esc(v)}</b></button>`).join('')}
   <b>Itens (${L2.length})</b><div class="row"><button class="btn sm" data-cp="${esc(L2.map(l=>l.cod).join('\n'))}">Copiar só os códigos</button><button class="btn sm" data-cp="${esc(L2.map(l=>l.qt).join('\n'))}">Copiar só as quantidades</button><button class="btn sm ghost" id="trx">Baixar Excel</button></div>
   <table class="t"><tr><th>Código</th><th class="n">Qtd.</th><th class="n">Unit. s/ IPI</th><th class="n">Total</th></tr>${L2.map(l=>`<tr><td><button class="chip" data-cp="${esc(l.cod)}"><b>${esc(l.cod)}</b></button><div class="hint" style="font-size:11px">${esc(String(l.desc||'').slice(0,40))}</div></td><td class="n"><button class="chip" data-cp="${esc(l.qt)}"><b>${l.qt}</b></button></td><td class="n">${l.pu?`<button class="chip" data-cp="${esc(fmtN(l.pu))}">${brl(l.pu)}</button>`:'—'}</td><td class="n">${l.pu?brl(l.pu*l.qt):'—'}</td></tr>`).join('')}</table>
   <div class="card grid" style="background:var(--surface2)"><div class="row" style="justify-content:space-between"><span>Subtotal (sem IPI)</span><b>${brl(sub)}</b></div><div class="row" style="justify-content:space-between"><span>IPI</span><b>${brl(ipi)}</b></div><div class="tot" style="margin:0"><span>Total para conferir na fábrica</span><b>${brl(sub?sub+ipi:o.total)}</b></div><p class="hint" style="margin:0">${L2.length} itens · ${L2.reduce((s,l)=>s+(+l.qt||0),0)} unidades</p></div>
   <div class="r2"><label class="f">Nº do pedido gerado na fábrica<input id="trn" value="${esc(d.num_fabrica||'')}" placeholder="ex.: 123456"></label><label class="f">Data programada de faturamento (se for para frente)<input id="trd" type="date" value="${esc(d.programado||'')}"></label></div>
   <label class="row" style="gap:6px"><input id="trv" type="checkbox" style="width:auto"${L('lancarVendas')?' checked':''}> Lançar nas vendas do sistema <span class="hint">(desmarque enquanto o pedido também for digitado no Reprio, para não contar em dobro)</span></label>
   <button class="btn" id="trok">✓ Marcar como transmitido</button></div>`; document.body.appendChild(ov);
  let obsOk=!d.obs; const avisoObs=()=>new Promise(res=>{const p=document.createElement('div'); p.className='ov'; p.style.zIndex=60; p.innerHTML=`<div class="sh grid" style="border:3px solid var(--warn)"><b class="warn" style="font-size:20px">⚠️ Este pedido tem observação</b><div class="card" style="white-space:pre-wrap;font-size:16px">${esc(d.obs)}</div><label class="row" style="gap:8px;font-size:15px"><input id="obck" type="checkbox" style="width:22px;height:22px"> Li e coloquei esta observação no pedido da fábrica</label><div class="row"><button class="btn" id="obok" disabled>Confirmar</button><button class="btn ghost" id="obno">Voltar</button></div></div>`; document.body.appendChild(p);
    p.querySelector('#obck').onchange=e=>p.querySelector('#obok').disabled=!e.target.checked; p.querySelector('#obok').onclick=()=>{p.remove(); res(true)}; p.querySelector('#obno').onclick=()=>{p.remove(); res(false)}});
  if(d.obs) setTimeout(async()=>{obsOk=await avisoObs()},300);
  ov.onclick=async e=>{const t=e.target; if(t.closest('[data-x]')||t===ov) return ov.remove(); const cp=t.closest('[data-cp]'); if(cp){try{await navigator.clipboard.writeText(cp.dataset.cp); cp.style.borderColor='var(--ok)'; cp.style.outline='2px solid var(--ok)'; toast('Copiado')}catch(_){toast('Não consegui copiar')} return}
    if(t.id==='trx'){await loadXLSX(); const ws=XLSX.utils.aoa_to_sheet([['Código','Descrição','Quantidade','Preço unit.','Total'],...L2.map(l=>[l.cod,l.desc||'',l.qt,l.pu||'',(l.pu||0)*l.qt]),[],['','','','Total',o.total||sub+ipi]]); const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb,ws,'Pedido'); return XLSX.writeFile(wb,`Pedido_${repName(rep)}_${(o.cliente||'').split(' ')[0]}.xlsx`)}
    if(t.id==='trok'){if(!obsOk){obsOk=await avisoObs(); if(!obsOk) return} const n=ov.querySelector('#trn').value.trim(), dp=ov.querySelector('#trd').value||null, lv=ov.querySelector('#trv').checked; LS('lancarVendas',lv); t.disabled=true;
      const nd={...d,num_fabrica:n||null,programado:dp,transmitido_em:new Date().toISOString(),transmitido_por:meuNome(),obs_conferida:!!d.obs};
      try{await api(`orcamentos?id=eq.${encodeURIComponent(o.id)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'transmitido',dados:nd,atualizado_em:new Date().toISOString()})});
        if(lv){const pid='sis-'+o.id; try{await api('pedidos?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify([{id:pid,origem:'sistema',num:n||null,representada:HIST_REP[rep]||repName(rep),cnpj:o.cnpj||c.cnpj||null,cliente:o.cliente||c.n||null,cidade:c.cid||null,data:hoje(),data_fat:dp,valor:Math.round(sub*100)/100,valor_imp:o.total||null,prazo:d.prazo||null,vendedor:String(d.vend||meuNome()).split(' ')[0].toUpperCase(),status:'finalizado',tabela:T?T.nome:null,itens:L2.length,qtd:L2.reduce((s,l)=>s+(+l.qt||0),0),oc:d.oc||null}])});
          await api('pedido_itens?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(L2.map((l,k)=>({id:pid+'-'+k,pedido_id:pid,cod:l.cod,descricao:l.desc||null,qtd:+l.qt||0,preco:+l.pu||0,total:(+l.pu||0)*(+l.qt||0)})))})}catch(err){toast('Transmitido, mas não lancei nas vendas: '+err.message.slice(0,80))}}
        fecharFollowUps(o.id,'Transmitido'+(n?' nº '+n:'')); ov.remove(); toast('Pedido marcado como transmitido'); if(route==='trans') paraTransmitir(); else if(route==='ped') ped()}catch(err){toast('Erro: '+err.message); t.disabled=false}}}}
async function paraTransmitir(){const m=$('#main'); let O=[]; try{O=await api('orcamentos?select=*&status=eq.aprovado_transmissao&order=atualizado_em')}catch(e){}
  m.innerHTML=`<div class="row" style="justify-content:space-between"><div class="sec" style="margin:0">Para transmitir</div><button class="chip" data-gm2="ped">Todos os pedidos ›</button></div><p class="hint">Orçamentos aprovados aguardando lançamento no portal da fábrica.</p>
   ${O.map(o=>`<button class="card" data-tr="${esc(o.id)}" style="display:block;width:100%;text-align:left;margin-bottom:8px;color:inherit;font:inherit;cursor:pointer"><div class="row" style="justify-content:space-between"><b>${repIcon(o.app,20)} ${esc(o.cliente||'')}</b><b>${brl(o.total)}</b></div><div class="hint">${esc(repName(o.app))} · ${o.itens} itens · aprovado ${new Date(o.atualizado_em).toLocaleDateString('pt-BR')}${o.dados&&o.dados.oc?' · OC '+esc(o.dados.oc):''}${o.dados&&o.dados.origem==='b2b'?' · Portal B2B':''}</div></button>`).join('')||'<p class="hint">Nada para transmitir agora. 👍</p>'}`;
  m.onclick=e=>{if(e.target.closest('[data-gm2]')) return go('ped'); const b=e.target.closest('[data-tr]'); if(b) transmitir(O.find(x=>x.id===b.dataset.tr))}}

/* ================= Produtos: inativar (excluir) sem perder histórico ================= */
async function inativarProdutos(rep,ids,ativo){for(let i=0;i<ids.length;i+=150) await api(`produtos?id=in.(${ids.slice(i,i+150).join(',')})`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({ativo,atualizado_em:new Date().toISOString()})});
  await api('alteracoes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({rep,tipo:ativo?'reativacao':'exclusao',resumo:{itens:ids.length}})}).catch(()=>{}); STALE.add('cat_'+rep); delete CAT[rep]; STALE.add('reps'); REPS=null}

/* exclusão com duas etapas */
function confirmaExclusao(oque){return new Promise(res=>{if(!confirm(`Excluir ${oque}?`)) return res(false); const p=document.createElement('div'); p.className='ov'; p.style.zIndex=60; p.innerHTML=`<div class="sh grid" style="border:3px solid var(--bad)"><b class="bad" style="font-size:18px">Confirmação final</b><p>Esta ação não pode ser desfeita. Para excluir ${esc(oque)}, digite <b>EXCLUIR</b> abaixo.</p><input id="cxi" autocomplete="off" placeholder="EXCLUIR"><div class="row"><button class="btn" id="cxo" style="background:var(--bad)" disabled>Excluir definitivamente</button><button class="btn ghost" id="cxn">Cancelar</button></div></div>`; document.body.appendChild(p);
  p.querySelector('#cxi').oninput=e=>p.querySelector('#cxo').disabled=e.target.value.trim().toUpperCase()!=='EXCLUIR'; p.querySelector('#cxo').onclick=()=>{p.remove(); res(true)}; p.querySelector('#cxn').onclick=()=>{p.remove(); res(false)}; setTimeout(()=>p.querySelector('#cxi').focus(),50)})}

/* PDF padrão a partir de linhas salvas (orçamentos salvos, pedidos do histórico) */
async function pdfDeLinhas(rep,cli,linhas,meta){const C=rep?await catalog(rep).catch(()=>[]):[]; const T=rep&&meta.tabela?(await tabelas(rep).catch(()=>[])).find(t=>t.id==meta.tabela):null;
  const rows=linhas.map(l=>{const k=norm(l.cod).trim(); const p=C.find(x=>norm(x.cod).trim()===k||norm(x.ref||'').trim()===k)||{}; const pu=+l.pu||0, qt=+l.qt||0; const pp={...p,cod:l.cod,descricao:p.descricao||l.desc||'',ipi:p.ipi??l.ipi,ncm:p.ncm||l.ncm,attrs:{...(p.attrs||{}),ean:(p.attrs||{}).ean||l.ean}};
    return {i:{qt,pid:p.id},p:pp,pu,tot:pu*qt,ipiv:pu*qt*(+pp.ipi||0)/100}});
  const sub=rows.reduce((s,r)=>s+r.tot,0), ipi=rows.reduce((s,r)=>s+r.ipiv,0); if(!sub) return toast('Este registro não guardou preços; não dá para gerar o PDF.');
  const o={rep:rep||'',cli,prazo:meta.prazo||'',obs:meta.obs||'',oc:meta.oc||'',vend:meta.vend||'',transpN:meta.transpN||''}; await pdf(o,rows,{sub,ipi,fr:0,tab:T,mode:'dl'})}

/* ================= motivos de perda ================= */
const MOTIVOS=['Preço acima do concorrente','Prazo de entrega','Comprou do concorrente','Sem estoque / produto indisponível','Cliente desistiu / sem demanda','Crédito / financeiro','Pedido mínimo não atingido','Frete','Produto não atende (técnico)','Erro / orçamento duplicado','Outro'];
function perguntaMotivo(){return new Promise(res=>{const p=document.createElement('div'); p.className='ov'; p.style.zIndex=60; let m='';
  p.innerHTML=`<div class="sh grid"><b style="font-size:18px">Por que perdemos este orçamento?</b><p class="hint" style="margin:0">O motivo entra no relatório “Motivos de perda”.</p><div class="row">${MOTIVOS.map(x=>`<button class="chip" data-mv="${esc(x)}">${esc(x)}</button>`).join('')}</div><textarea id="mvo" rows="2" placeholder="Detalhe (ex.: concorrente e preço que o cliente recebeu)"></textarea><div class="row"><button class="btn" id="mvok" disabled>Cancelar orçamento com este motivo</button><button class="btn ghost" id="mvx">Voltar</button></div></div>`; document.body.appendChild(p);
  p.onclick=e=>{const b=e.target.closest('[data-mv]'); if(b){m=b.dataset.mv; p.querySelectorAll('[data-mv]').forEach(x=>x.classList.toggle('on',x===b)); p.querySelector('#mvok').disabled=false; return} if(e.target.id==='mvok'){p.remove(); res({m,o:p.querySelector('#mvo').value.trim()})} if(e.target.id==='mvx'){p.remove(); res(null)}}})}
async function setStatus(id,st){const body={status:st,atualizado_em:new Date().toISOString()};
  if(st==='cancelado'){const mv=await perguntaMotivo(); if(!mv) throw new Error('Cancelamento desistido (sem motivo)'); const [row]=await api(`orcamentos?select=dados&id=eq.${encodeURIComponent(id)}`); body.dados={...((row&&row.dados)||{}),motivo_perda:mv.m,motivo_obs:mv.o||null,perdido_em:new Date().toISOString(),perdido_por:meuNome()}}
  await api(`orcamentos?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(body)});
  if(st==='cancelado'||st==='transmitido') fecharFollowUps(id,stLbl(st))}

/* ================= fotos dos itens nas listas ================= */
const IMGC={}; async function mapaFotos(reps_){for(const r of [...new Set(reps_)].filter(Boolean)){if(IMGC[r]) continue; try{const C=await catalog(r); const m={}; C.forEach(p=>{if(p.img){m[norm(p.cod).trim()]=p.img; if(p.ref) m[norm(p.ref).trim()]=p.img}}); IMGC[r]=m}catch(e){IMGC[r]={}}}}
const fotoDe=(rep,cod)=>(IMGC[rep]||{})[norm(cod).trim()]||'';
function miniaturas(rep,linhas,n){const L=(linhas||[]).filter(l=>fotoDe(rep,l.cod)).slice(0,n||5); return L.length?`<div class="row" style="gap:4px;margin-top:6px">${L.map(l=>`<img src="${esc(fotoDe(rep,l.cod))}" data-zoom="${esc(fotoDe(rep,l.cod))}" data-cap="${esc(l.cod)}" alt="" loading="lazy" style="width:38px;height:38px;object-fit:contain;background:#fff;border-radius:6px;cursor:zoom-in" onerror="this.remove()">`).join('')}${(linhas||[]).length>L.length?`<span class="hint">+${(linhas||[]).length-L.length}</span>`:''}</div>`:''}

/* ================= quadro (kanban) de orçamentos e pedidos ================= */
async function quadro(box,O,onOpen){await mapaFotos(O.map(o=>(o.dados&&o.dados.rep)||o.app)); if(!box.isConnected) return;
  const col=k=>O.filter(o=>stOf(o)===k);
  box.innerHTML=`<div class="kanban">${STATUS.map(([k,l,c])=>{const L=col(k); return `<div class="kcol"><div class="khead" style="border-top:4px solid ${c}"><b>${l}</b><span class="hint">${L.length} · ${brl(L.reduce((s,o)=>s+(+o.total||0),0))}</span></div>
     ${L.slice(0,60).map(o=>{const d=o.dados||{}; const rep=d.rep||o.app; const lin=d.linhas||[]; const nf=d.num_fabrica||o.num_fabrica; const idade=Math.max(0,dias(String(o.atualizado_em).slice(0,10)));
       return `<div class="kcard" data-od="${esc(o.id)}"><div class="row" style="justify-content:space-between;flex-wrap:nowrap"><b style="font-size:13px">${repIcon(rep,18)} ${esc(o.cliente||'Sem cliente')}</b></div>
        <div class="row" style="justify-content:space-between"><b>${brl(o.total)}</b><span class="hint">${idade}d</span></div>
        <div class="hint" style="font-size:12px">${esc(repName(rep))} · ${o.itens||lin.length} itens${d.oc?' · OC '+esc(d.oc):''}${o.origem==='reprio'?' · Reprio':''}${d.origem==='b2b'?' · Portal':''}</div>
        ${nf?`<div style="font-size:12px"><b>Fábrica nº ${esc(nf)}</b>${o.situacao_fabrica?' · '+esc(o.situacao_fabrica):''}</div>`:''}${d.programado?`<div class="hint" style="font-size:12px">📅 programado ${esc(d.programado.split('-').reverse().join('/'))}</div>`:''}${k==='cancelado'&&d.motivo_perda?`<div class="bad" style="font-size:12px">✖ ${esc(d.motivo_perda)}</div>`:''}

        </div>`}).join('')}${L.length>60?`<p class="hint">+${L.length-60}</p>`:''}</div>`}).join('')}</div>`;
  box.onclick=async e=>{const card=e.target.closest('[data-od]'); if(!card) return; const o=O.find(x=>x.id===card.dataset.od);
    const mv=e.target.closest('[data-mv2]'); if(mv){e.stopPropagation(); try{await setStatus(o.id,mv.dataset.mv2); o.status=mv.dataset.mv2; toast('Movido para: '+stLbl(o.status)); if(o.status==='cancelado'){const [r]=await api(`orcamentos?select=dados&id=eq.${encodeURIComponent(o.id)}`); o.dados=r&&r.dados||o.dados} quadro(box,O,onOpen)}catch(err){toast(err.message.slice(0,90))} return}
    if(e.target.closest('[data-trq]')){e.stopPropagation(); return transmitir(o)} if(e.target.closest('img[data-zoom]')) return; onOpen(o)}}

/* ================= relatório: motivos de perda ================= */
async function relPerdas(box,anos,repF){box.innerHTML='<p class="hint">Calculando…</p>'; const de=ymd(new Date(Date.now()-anos*365*864e5));
  const O=await apiAll(`orcamentos?select=id,app,cliente,total,status,atualizado_em,user_id,dados&status=eq.cancelado&atualizado_em=gte.${de}`).catch(()=>[]);
  const R2=await apiAll(`pedidos?select=id,representada,cliente,valor,vendedor,data&origem=eq.reprio&status=eq.cancelado&data=gte.${de}`).catch(()=>[]);
  const L=[...O.map(o=>({rep:repName(o.app),cli:o.cliente,v:+o.total||0,mot:(o.dados&&o.dados.motivo_perda)||'Sem motivo informado',obs:o.dados&&o.dados.motivo_obs,vend:(o.dados&&o.dados.vend)||'',dt:String(o.atualizado_em).slice(0,10)})),...R2.map(p=>({rep:p.representada,cli:p.cliente,v:+p.valor||0,mot:'Cancelado no Reprio (sem motivo)',vend:p.vendedor||'',dt:p.data}))].filter(x=>!repF||x.rep===repF);
  const grp=k=>{const g={}; L.forEach(x=>{const a=g[x[k]||'—']=g[x[k]||'—']||{n:0,v:0}; a.n++; a.v+=x.v}); return Object.entries(g).sort((a,b)=>b[1].v-a[1].v)};
  const tot=L.reduce((s,x)=>s+x.v,0); const tab=(t,arr)=>`<div class="card" style="margin-bottom:12px"><b>${t}</b><table class="t"><tr><th>${t.split(' ').pop()}</th><th class="n">Qtd.</th><th class="n">Valor perdido</th><th class="n">%</th></tr>${arr.map(([k,a])=>`<tr><td>${esc(k)}</td><td class="n">${a.n}</td><td class="n">${brl(a.v)}</td><td class="n">${tot?(a.v/tot*100).toFixed(0):0}%</td></tr>`).join('')}</table></div>`;
  box.innerHTML=`<div class="kpis" style="margin-bottom:12px"><div class="kpi"><small>Orçamentos perdidos</small><b>${L.length}</b></div><div class="kpi"><small>Valor perdido</small><b>${brl(tot)}</b></div></div>`+tab('Por motivo',grp('mot'))+tab('Por representada',grp('rep'))+tab('Por vendedor',grp('vend'))+
   `<div class="card"><b>Detalhe</b><table class="t"><tr><th>Data</th><th>Cliente</th><th>Representada</th><th>Motivo</th><th class="n">Valor</th></tr>${L.sort((a,b)=>String(b.dt).localeCompare(a.dt)).slice(0,300).map(x=>`<tr><td>${esc(String(x.dt).split('-').reverse().join('/'))}</td><td>${esc(x.cli||'')}</td><td>${esc(x.rep)}</td><td>${esc(x.mot)}${x.obs?`<div class="hint">${esc(x.obs)}</div>`:''}</td><td class="n">${brl(x.v)}</td></tr>`).join('')}</table></div>`;
  box._csv=[['Data','Cliente','Representada','Vendedor','Motivo','Detalhe','Valor'],...L.map(x=>[x.dt,x.cli,x.rep,x.vend,x.mot,x.obs||'',x.v])]}

/* ================= e-mail pelo sistema (remetente = e-mail do vendedor) ================= */
const b64=blob=>new Promise(res=>{const r=new FileReader(); r.onload=()=>res(String(r.result).split(',')[1]); r.readAsDataURL(blob)});
async function emailsDoCliente(cnpj){const out=[]; if(!cnpj) return out; try{const [c]=await api(`clientes?select=email,razao,reprio&cnpj=eq.${cnpj}`); if(c){const e=c.email||(c.reprio||{}).email; String(e||'').split(/[;,\s]+/).filter(x=>/@/.test(x)).forEach(x=>out.push({e:x.toLowerCase(),n:'Cadastro',p:true}))}}catch(e){}
  try{(await api(`cliente_pessoas?select=nome,cargo,email,principal&cnpj=eq.${cnpj}&email=not.is.null&order=principal.desc`)).forEach(p=>{if(p.email&&!out.some(x=>x.e===p.email.toLowerCase())) out.push({e:p.email.toLowerCase(),n:p.nome+(p.cargo?' · '+p.cargo:''),p:p.principal})})}catch(e){}
  const C=await clientes().catch(()=>[]); const c2=C.find(x=>x.cnpj===cnpj); if(c2&&c2.em&&!out.some(x=>x.e===c2.em.toLowerCase())) out.push({e:c2.em.toLowerCase(),n:'Cadastro'}); return out}
async function enviarEmail({cnpj,cliente,assunto,texto,gerarPDF,ref}){const L=await emailsDoCliente(cnpj); let hist=[]; try{hist=await api(`email_envios?select=*&ref_id=eq.${encodeURIComponent(ref.id)}&order=enviado_em.desc`)}catch(e){}
  const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="sh grid"><div class="row" style="justify-content:space-between"><b style="font-size:18px">✉️ Enviar por e-mail</b><button class="chip" data-x>✕</button></div><div class="hint">${esc(cliente||'')}</div>
   <div class="card grid" style="background:var(--surface2)"><b style="font-size:13px">E-mails do cliente</b>${L.map((x,i)=>`<label class="row" style="gap:8px"><input type="checkbox" data-em="${esc(x.e)}"${i===0||x.p?' checked':''} style="width:20px;height:20px"> ${esc(x.e)} <span class="hint">${esc(x.n||'')}</span></label>`).join('')||'<span class="hint">Nenhum e-mail cadastrado. Digite abaixo ou cadastre em Clientes › Contatos.</span>'}</div>
   <label class="f">Outro(s) e-mail(s)<input id="emo" placeholder="separe por vírgula"></label><label class="f">Cópia (CC)<input id="emc" placeholder="opcional" value="${esc((perfil&&perfil.email_envio)||'')}"></label>
   <label class="f">Assunto<input id="ems" value="${esc(assunto)}"></label><label class="f">Mensagem<textarea id="emt" rows="7">${esc(texto)}</textarea></label>
   <label class="row" style="gap:8px"><input id="ema" type="checkbox" checked style="width:20px;height:20px"> Anexar o PDF do orçamento</label>
   ${hist.length?`<details><summary class="hint" style="cursor:pointer">Histórico de envios (${hist.length})</summary>${hist.map(h=>`<div class="hint">${new Date(h.enviado_em).toLocaleString('pt-BR')} · ${esc((h.para||[]).join(', '))} · ${h.status==='enviado'?'✓ enviado':'✖ '+esc(h.erro||'erro')}</div>`).join('')}</details>`:''}
   <div class="row"><button class="btn" id="emok">Enviar e-mail</button><button class="btn ghost" data-x>Cancelar</button></div><div class="hint" id="emst"></div></div>`; document.body.appendChild(ov);
  ov.onclick=async e=>{const t=e.target; if(t.closest('[data-x]')||t===ov) return ov.remove(); if(t.id!=='emok') return;
    const para=[...ov.querySelectorAll('[data-em]:checked')].map(x=>x.dataset.em).concat(ov.querySelector('#emo').value.split(/[;,\s]+/).filter(x=>/@/.test(x))); const cc=ov.querySelector('#emc').value.split(/[;,\s]+/).filter(x=>/@/.test(x));
    if(!para.length) return toast('Escolha ou digite ao menos um e-mail'); t.disabled=true; const st=ov.querySelector('#emst'); st.textContent='Gerando PDF…';
    try{let anexo=null; if(ov.querySelector('#ema').checked){const g=await gerarPDF(); anexo={nome:g.fname,base64:await b64(g.blob)}} st.textContent='Enviando…';
      const tk=await token(); const r=await fetch(SB+'/functions/v1/enviar-email',{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+tk,'Content-Type':'application/json'},body:JSON.stringify({para,cc,assunto:ov.querySelector('#ems').value,texto:ov.querySelector('#emt').value,anexo,ref})});
      const j=await r.json().catch(()=>({})); if(r.status===404) throw new Error('O envio pelo sistema ainda não foi ativado (Edge Function “enviar-email”). Veja Mais › Ajustes.'); if(!r.ok) throw new Error(j.erro||('HTTP '+r.status));
      ov.remove(); toast('✓ E-mail enviado de '+(j.de||'seu e-mail'))}catch(err){st.textContent=''; t.disabled=false; toast(err.message.slice(0,160))}}}

function fichaTopo(F){return `<div class="ftopo">${F.map(([l,v,big])=>`<div class="${big?'ft-big':''}"><small>${esc(l)}</small><b>${esc(v)}</b></div>`).join('')}</div>`}

/* ================= numeração própria (formato Reprio) ================= */
async function garantirNumero(o){if(o.num) return o.num; try{const n=await api('rpc/proximo_numero',{method:'POST',body:'{}'}); if(typeof n==='string'&&n){o.num=n; if(!o.oc) o.oc=n; saveQ(o)}}catch(e){} return o.num}

/* ================= preço negociado (com histórico) ================= */
function negociarPreco(o,pid,novo,tabPreco){const it=o.itens.find(i=>i.pid===pid); if(!it) return; const de=it.pu!=null?it.pu:tabPreco; novo=Math.round((+novo||0)*100)/100; if(!novo||Math.abs(novo-de)<0.005) return;
  it.neg=[...(it.neg||[]),{de,para:novo,tab:tabPreco,por:meuNome(),em:new Date().toISOString()}]; it.pu=Math.abs(novo-tabPreco)<0.005?null:novo; if(it.pu==null) delete it.pu; saveQ(o)}

/* ================= metas ================= */
async function metasDoMes(y,mo){try{return await api(`metas?select=*&ano=eq.${y}&mes=eq.${mo+1}`)}catch(e){return null}}
async function metasView(){const m=$('#main'); const st=Object.assign({y:new Date().getFullYear(),mo:new Date().getMonth()},L('metasF')||{}); const R=(await reps()).filter(r=>r.ativa); const V=await vendedores();
  const M=await metasDoMes(st.y,st.mo); if(!m.isConnected) return; if(M===null){m.innerHTML='<div class="sec">Metas</div><p class="warn">Rode o arquivo 13_numeracao_metas.sql no Supabase para ativar as metas.</p>';return}
  const g=(t,k)=>M.find(x=>x.tipo===t&&x.chave===k)||{}; const ges=ehGestor(); const ro=ges?'':' readonly';
  const linha=(t,k,lbl)=>`<tr><td>${lbl}</td><td class="n"><input data-mt="${t}" data-mk="${esc(k)}" data-mf="valor" type="number" step="100" value="${g(t,k).valor??''}" placeholder="R$" style="width:130px;padding:6px"${ro}></td><td class="n"><input data-mt="${t}" data-mk="${esc(k)}" data-mf="positivacao" type="number" value="${g(t,k).positivacao??''}" placeholder="clientes" style="width:90px;padding:6px"${ro}></td></tr>`;
  m.innerHTML=`<div class="row" style="justify-content:space-between"><div class="sec" style="margin:0">Metas</div><div class="row"><select id="mmo">${MESES.map((n,i)=>`<option value="${i}"${i===st.mo?' selected':''}>${n}</option>`).join('')}</select><select id="my">${[0,1].map(i=>new Date().getFullYear()+i-0).concat([new Date().getFullYear()-1]).sort().map(y=>`<option${y===st.y?' selected':''}>${y}</option>`).join('')}</select></div></div>
   <p class="hint">Meta de faturamento (sem impostos) e de positivação (clientes diferentes que compraram) para ${MESES[st.mo]}/${st.y}. ${ges?'Salva sozinho ao sair do campo.':'Somente gestores editam.'}</p>
   <div class="card" style="overflow-x:auto"><table class="t"><tr><th>Geral</th><th class="n">Faturamento</th><th class="n">Positivação</th></tr>${linha('geral','TOTAL','<b>Empresa</b>')}</table></div>
   <div class="card" style="overflow-x:auto;margin-top:10px"><table class="t"><tr><th>Por representada</th><th class="n">Faturamento</th><th class="n">Positivação</th></tr>${R.map(r=>linha('rep',HIST_REP[r.id]||r.nome,repIcon(r,18)+' '+esc(r.nome))).join('')}</table></div>
   <div class="card" style="overflow-x:auto;margin-top:10px"><table class="t"><tr><th>Por vendedor</th><th class="n">Faturamento</th><th class="n">Positivação</th></tr>${V.map(v=>linha('vend',v,esc(v))).join('')}</table></div>
   ${ges?'<button class="btn ghost" id="mcop" style="margin-top:10px">Copiar metas do mês anterior</button>':''}`;
  m.onchange=async e=>{const i=e.target; if(i.id==='mmo'){st.mo=+i.value; LS('metasF',st); return metasView()} if(i.id==='my'){st.y=+i.value; LS('metasF',st); return metasView()}
    if(!i.dataset.mt) return; const t=i.dataset.mt,k=i.dataset.mk; const row={ano:st.y,mes:st.mo+1,tipo:t,chave:k,...g(t,k)}; delete row.id; row[i.dataset.mf]=i.value===''?null:+i.value;
    try{await api('metas?on_conflict=ano,mes,tipo,chave',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(row)}); i.style.borderColor='var(--ok)'; const ex=M.find(x=>x.tipo===t&&x.chave===k); if(ex) Object.assign(ex,row); else M.push(row)}catch(err){toast('Erro: '+err.message)}};
  m.onclick=async e=>{if(e.target.id!=='mcop') return; const pm=st.mo?st.mo-1:11, py=st.mo?st.y:st.y-1; const P=await metasDoMes(py,pm)||[]; if(!P.length) return toast('Mês anterior sem metas'); await api('metas?on_conflict=ano,mes,tipo,chave',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(P.map(({id,...x})=>({...x,ano:st.y,mes:st.mo+1})))}); toast('Metas copiadas'); metasView()}}

/* ================= relatório: conversão e positivação mês a mês ================= */
async function relConversao(box,repF){box.innerHTML='<p class="hint">Calculando…</p>'; const hoje_=new Date(); const meses=[]; for(let i=11;i>=0;i--){const d=new Date(hoje_.getFullYear(),hoje_.getMonth()-i,1); meses.push([d.getFullYear(),d.getMonth()])}
  const de=mesIni(meses[0][0],meses[0][1]);
  const [P,O]=await Promise.all([apiAll(`pedidos?select=representada,cnpj,valor,status,origem,data:data_ref,vendedor&data_ref=gte.${de}`).catch(()=>[]),apiAll(`orcamentos?select=app,status,situacao,total,atualizado_em,cnpj&atualizado_em=gte.${de}`).catch(()=>[])]);
  const rows=meses.map(([y,mo])=>{const ini=mesIni(y,mo), fim=mesFim(y,mo); const pm=P.filter(p=>p.data>=ini&&p.data<=fim&&(!repF||p.representada===repF)); const om=O.filter(o=>String(o.atualizado_em).slice(0,10)>=ini&&String(o.atualizado_em).slice(0,10)<=fim&&(!repF||repName(o.app)===repF));
    const rep=pm.filter(p=>p.origem==='reprio'); const ganhos=rep.filter(p=>EFET.includes(p.status)).length, perd=rep.filter(p=>p.status==='cancelado').length, abertos=rep.filter(p=>p.status==='rascunho'||p.status==='em_digitacao').length;
    const sGan=om.filter(o=>stOf(o)==='transmitido').length, sPer=om.filter(o=>stOf(o)==='cancelado').length, sAb=om.filter(o=>!['transmitido','cancelado'].includes(stOf(o))).length;
    const tot=ganhos+perd+abertos+sGan+sPer+sAb, ganho=ganhos+sGan; const efet=pm.filter(p=>!p.status||EFET.includes(p.status));
    return {lbl:MESES[mo].slice(0,3)+'/'+String(y).slice(2),tot,ganho,perd:perd+sPer,ab:abertos+sAb,taxa:tot?ganho/tot*100:0,fat:efet.reduce((s,p)=>s+(+p.valor||0),0),pos:new Set(efet.map(p=>p.cnpj)).size}});
  const mx=Math.max(1,...rows.map(r=>r.taxa)); const ult=rows[rows.length-1], pen=rows[rows.length-2]||{taxa:0};
  box.innerHTML=`<div class="kpis" style="margin-bottom:12px"><div class="kpi"><small>Conversão no mês</small><b>${ult.taxa.toFixed(0)}%</b><small class="${ult.taxa>=pen.taxa?'ok':'bad'}">${ult.taxa>=pen.taxa?'▲':'▼'} ${Math.abs(ult.taxa-pen.taxa).toFixed(0)} p.p. vs mês anterior</small></div><div class="kpi"><small>Orçamentos no mês</small><b>${ult.tot}</b><small>${ult.ganho} fechados · ${ult.perd} perdidos · ${ult.ab} em aberto</small></div><div class="kpi"><small>Positivação no mês</small><b>${ult.pos}</b><small>mês anterior: ${pen.pos||0}</small></div><div class="kpi"><small>Faturamento no mês</small><b>${brl(ult.fat)}</b></div></div>
   <div class="card"><b>Taxa de conversão (orçamentos que viraram pedido)</b><div class="cbar">${rows.map(r=>`<div title="${r.lbl}: ${r.taxa.toFixed(1)}%"><span style="height:${r.taxa/mx*100}%"></span><small>${r.taxa.toFixed(0)}%</small><small>${r.lbl}</small></div>`).join('')}</div></div>
   <div class="card" style="overflow-x:auto;margin-top:12px"><table class="t"><tr><th>Mês</th><th class="n">Orçamentos</th><th class="n">Fechados</th><th class="n">Perdidos</th><th class="n">Em aberto</th><th class="n">Conversão</th><th class="n">Positivação</th><th class="n">Faturamento</th></tr>${rows.slice().reverse().map(r=>`<tr><td>${r.lbl}</td><td class="n">${r.tot}</td><td class="n ok">${r.ganho}</td><td class="n bad">${r.perd}</td><td class="n">${r.ab}</td><td class="n"><b>${r.taxa.toFixed(1)}%</b></td><td class="n">${r.pos}</td><td class="n">${brl(r.fat)}</td></tr>`).join('')}</table>
   <p class="hint">Conversão = fechados ÷ (fechados + perdidos + em aberto) dos orçamentos do mês (Reprio + sistema).</p></div>`;
  box._csv=[['Mês','Orçamentos','Fechados','Perdidos','Em aberto','Conversão %','Positivação','Faturamento'],...rows.map(r=>[r.lbl,r.tot,r.ganho,r.perd,r.ab,r.taxa.toFixed(1),r.pos,r.fat])]}

/* ================= tarefa: abrir, ver, ir para orçamento/cliente ================= */
async function abrirTarefa(t){if(typeof t!=='object'){try{t=(await api(`tarefas?select=*&id=eq.${t}`))[0]}catch(e){} if(!t) return}
  const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="sh grid"><div class="row" style="justify-content:space-between;align-items:flex-start"><b style="font-size:18px">${esc(TT[t.tipo]||'✔️ Tarefa')} · ${esc(t.titulo)}</b><button class="chip" data-x>✕</button></div>
   ${fichaTopo([['Quando',t.vence.split('-').reverse().join('/')+(t.hora?' às '+t.hora:''),0],['Responsável',t.responsavel_nome||'Equipe'],['Cliente',t.cliente||'—'],['Representada',t.rep?repName(t.rep):'—']])}
   ${t.obs?`<div class="card" style="white-space:pre-wrap">${esc(t.obs)}</div>`:'<p class="hint" style="margin:0">Sem observações.</p>'}
   ${t.feita?`<p class="ok">✓ Concluída ${t.feita_em?new Date(t.feita_em).toLocaleString('pt-BR'):''}${t.resultado?' · '+esc(t.resultado):''}</p>`:''}
   <div class="row">${t.orcamento_id?'<button class="btn ghost" data-to>📄 Abrir orçamento</button>':''}${t.cnpj?'<button class="btn ghost" data-tf>👤 Ficha do cliente</button><button class="btn ghost" data-tr>📞 Registrar contato</button>':''}</div>
   ${t.feita?'':`<label class="f">Resultado (opcional)<input id="tres" placeholder="ex.: cliente aprovou, vai enviar OC"></label><div class="row"><button class="btn" data-tok>✓ Concluir</button><button class="chip" data-ad="1">Amanhã</button><button class="chip" data-ad="3">+3 dias</button><button class="chip" data-ad="7">+7 dias</button><input id="tnd" type="date" style="width:auto"><input id="tnh" type="time" value="${esc(t.hora||'')}" style="width:auto"><button class="chip" data-rag>Reagendar</button></div>`}</div>`; document.body.appendChild(ov);
  const fim=()=>{ov.remove(); contaTarefas(); if(route==='tar') tarefasView()};
  ov.onclick=async e=>{const x=e.target; if(x.closest('[data-x]')||x===ov) return ov.remove();
    try{if(x.closest('[data-to]')){ov.remove(); return detOrc(t.orcamento_id)} if(x.closest('[data-tf]')){ov.remove(); return go('cli',{cnpj:t.cnpj})} if(x.closest('[data-tr]')){ov.remove(); return painelCliente(t.cnpj)}
      if(x.closest('[data-tok]')){await api(`tarefas?id=eq.${t.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({feita:true,feita_em:new Date().toISOString(),resultado:ov.querySelector('#tres').value.trim()||null})}); toast('Tarefa concluída'); return fim()}
      const a=x.closest('[data-ad]'); if(a){await api(`tarefas?id=eq.${t.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({vence:maisDias(+a.dataset.ad)})}); toast('Reagendada'); return fim()}
      if(x.closest('[data-rag]')){const d=ov.querySelector('#tnd').value, h=ov.querySelector('#tnh').value; if(!d&&!h) return toast('Escolha data ou hora'); await api(`tarefas?id=eq.${t.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({vence:d||t.vence,hora:h||null})}); toast('Reagendada'); return fim()}}catch(err){toast('Erro: '+err.message)}}}

/* ================= lembretes de tarefas (pop-up no canto da tela) ================= */
const AVISADAS=new Set(L('avisadas')||[]);
async function verificarLembretes(){if(!sess||!navigator.onLine) return; let T=[]; try{T=await api(`tarefas?select=*&feita=eq.false&vence=eq.${hoje()}&or=(responsavel.eq.${sess.uid},responsavel.is.null)&order=hora`)}catch(e){return}
  const agora=new Date(), min=agora.getHours()*60+agora.getMinutes();
  for(const t of T){const chave=t.id+'|'+t.vence+'|'+(t.hora||''); if(AVISADAS.has(chave)) continue; let mostrar=false;
    if(t.hora){const [h,mm]=t.hora.split(':').map(Number); const tm=h*60+mm; mostrar=tm-min<=15&&tm-min>=-60} else mostrar=min>=8*60;
    if(!mostrar) continue; AVISADAS.add(chave); LS('avisadas',[...AVISADAS].slice(-300)); lembrete(t);
    try{if('Notification' in window&&Notification.permission==='granted') new Notification('Chamae · '+(t.hora?t.hora+' · ':'')+t.titulo,{body:(t.cliente||'')+(t.obs?' — '+t.obs:''),icon:'icon-192.png',tag:'t'+t.id})}catch(e){}}}
function lembrete(t){let box=$('#lembretes'); if(!box){box=document.createElement('div'); box.id='lembretes'; document.body.appendChild(box)}
  const d=document.createElement('div'); d.className='lemb'; d.innerHTML=`<div class="row" style="justify-content:space-between;flex-wrap:nowrap;align-items:flex-start"><b>🔔 ${t.hora?esc(t.hora)+' · ':'Hoje · '}${esc(t.titulo)}</b><button class="chip" data-lx style="padding:2px 8px">✕</button></div>${t.cliente?`<div class="hint">${esc(t.cliente)}</div>`:''}<div class="row" style="margin-top:6px"><button class="btn sm" data-la>Abrir</button><button class="chip" data-l15>Adiar 15 min</button></div>`;
  d.onclick=async e=>{if(e.target.closest('[data-lx]')) return d.remove(); if(e.target.closest('[data-la]')){d.remove(); return abrirTarefa(t)}
    if(e.target.closest('[data-l15]')){const n=new Date(Date.now()+15*6e4); const h=String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0'); try{await api(`tarefas?id=eq.${t.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({hora:h})})}catch(_){} d.remove(); toast('Lembro de novo às '+h)}};
  box.appendChild(d); try{navigator.vibrate&&navigator.vibrate([150,80,150])}catch(e){}}
function iniciarLembretes(){verificarLembretes(); clearInterval(window._lembT); window._lembT=setInterval(verificarLembretes,60000);
  try{if('Notification' in window&&Notification.permission==='default'&&!L('notifPerg')){LS('notifPerg',1); setTimeout(()=>{if(confirm('Quer receber avisos das tarefas no horário, mesmo com o app em segundo plano?')) Notification.requestPermission()},4000)}}catch(e){}}

